function build(api) {
  var R = api.param("rows");
  var rng = api.rng;
  function lane(fromLeft) {
    return fromLeft ? rng.int(0, 3) : rng.int(5, 8);
  }
  // The road: one band of 3-4 lanes, alternating traffic direction
  var roadStart = Math.max(3, Math.floor(R * 0.12));
  var roadLen = rng.int(3, 4);
  var left = rng.int(0, 1) === 1;
  var roadEnd = roadStart - 1;
  for (var z = roadStart; z < roadStart + roadLen && z < R - 1; z++) {
    api.place("road", lane(left), z);
    left = !left;
    roadEnd = z;
  }
  // Then three little streams (1-2 rows each), spread out with grass between
  var after = roadEnd + 2;
  var avail = (R - 1) - after;
  var seg = Math.floor(avail / 3);
  if (seg < 3) { seg = 3; }
  for (var i = 0; i < 3; i++) {
    var base = after + i * seg;
    var maxOff = seg - 3;
    if (maxOff < 1) { maxOff = 1; }
    var s = base + rng.int(1, maxOff);
    var len = rng.int(1, 2);
    var dirLeft = rng.int(0, 1) === 1;
    for (var k = 0; k < len; k++) {
      var row = s + k;
      if (row >= R - 1 || row >= base + seg - 1) { break; }
      api.place("river", lane(dirLeft), row);
      dirLeft = !dirLeft;
    }
  }
}

function build(api) {
  var R = api.param("rows");
  var rng = api.rng;
  // Six-lane motorway: two carriageways of 3 lanes, split by a grass central reservation.
  // Total footprint 7 rows (3 road + 1 grass + 3 road).
  var minStart = 3;
  var maxStart = R - 1 - 7;
  var mid = Math.floor(R / 2) - 3;
  var lo = Math.max(minStart, mid - 4);
  var hi = Math.min(maxStart, mid + 4);
  if (hi < lo) { hi = lo; }
  var s = rng.int(lo, hi);
  var i;
  // First carriageway: traffic from the left
  for (i = 0; i < 3; i++) {
    if (s + i < R) { api.place("road", rng.int(0, 3), s + i); }
  }
  // Row s + 3 stays grass: the central reservation to rest on
  // Second carriageway: traffic from the right
  for (i = 4; i < 7; i++) {
    if (s + i < R) { api.place("road", rng.int(5, 8), s + i); }
  }
}

function build(api) {
  var R = api.param("rows");
  var rng = api.rng;
  var last = R - 1;
  function side() {
    return rng.int(0, 1) === 0 ? rng.int(0, 3) : rng.int(5, 8);
  }
  function band(kind, start, len) {
    var placed = 0;
    for (var i = 0; i < len; i++) {
      var z = start + i;
      if (z >= 3 && z <= last) { api.place(kind, side(), z); placed++; }
    }
    return placed;
  }
  // First railway crossing
  var z = 3 + rng.int(3, 6);
  var len1 = rng.int(1, 2);
  z += band("rail", z, len1);
  // Grass rest between the tracks
  z += rng.int(4, 7);
  // Second railway crossing
  var len2 = rng.int(1, 2);
  z += band("rail", z, len2);
  // Grass before the muddy river, placed later in the course
  z += rng.int(5, 8);
  var target = Math.floor(R * 0.6) + rng.int(0, 3);
  if (target > z) { z = target; }
  // Muddy river with floating logs: a full 3-row band
  var riverLen = 3;
  if (z + riverLen - 1 > last) { riverLen = last - z + 1; }
  if (riverLen > 0) { band("river", z, riverLen); }
}

